// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 seed, uint8 sendAmount) public {
        vm.assume(sendAmount > 0);
        address owner = address(uint160(uint256(keccak256(abi.encode(seed)))));
        vm.assume(owner != address(0) && owner != address(this) && owner != address(c));
        vm.prank(owner);
        c = new SimpleWallet();
        address donor = address(uint160(uint256(keccak256(abi.encode(seed, uint256(1))))));
        vm.assume(donor != address(0) && donor != owner && donor != address(this) && donor != address(c));
        vm.deal(donor, sendAmount + 1000);
        vm.prank(donor);
        (bool sent,) = address(c).call{value: sendAmount}("");
        require(sent, "donor send failed");
        uint256 balanceBefore = address(c).balance;
        uint256 ownerBalanceBefore = owner.balance;
        vm.prank(owner);
        c.withdrawAll();
        bool ok = (address(c).balance == 0) && (owner.balance == ownerBalanceBefore + balanceBefore);
        assertTrue(ok);
    }
}
